// Package dispatch implements the `entire dispatch` command: summarizes recent
// agent work into a dispatch-shaped bullet list, with optional LLM synthesis.
//
// Two modes:
//   - Server (default) — POST to the entire.io /dispatches endpoint; the server
//     runs the LLM using its own tokens and persists results for web viewing.
//   - Local (--local) — enumerate local checkpoints, batch-fetch per-checkpoint
//     analyses from the cloud, render client-side; with --generate, call the
//     user's configured LLM via the existing summarize package.
package dispatch

import "time"

// Mode selects between server-backed and local-only execution paths.
type Mode int

const (
	ModeServer Mode = iota
	ModeLocal
)

// Options holds all parsed CLI inputs for a dispatch run.
type Options struct {
	Mode        Mode
	RepoPaths   []string // --repos (local mode only)
	Org         string   // --org
	Since       string   // raw --since (duration, git-style, ISO)
	Until       string   // raw --until (defaults to "now" at runtime)
	Branches    []string // resolved branch names; ignored when AllBranches
	AllBranches bool
	Generate    bool
	Voice       string // raw --voice value; resolution happens in voices.go
	Format      string // "text" | "markdown" | "json"
	DryRun      bool
	Wait        bool
}

// Dispatch is the rendered, in-memory representation returned from either
// server or local mode. Fields like ID / WebURL are populated only for
// persisted (generate:true) server responses; bullets-only and dry-run
// responses leave them empty.
type Dispatch struct {
	ID              string
	FingerprintHash string
	WebURL          string
	Window          Window
	CoveredRepos    []string
	Repos           []RepoGroup
	Totals          Totals
	Warnings        Warnings
	GeneratedText   string

	DryRun            bool
	RequestedGenerate bool
	Generated         bool // true iff GeneratedText is set
	Deduped           bool
}

// Window captures the normalized time bounds and the actual first/last used
// checkpoint timestamps for display.
type Window struct {
	NormalizedSince   time.Time
	NormalizedUntil   time.Time
	FirstCheckpointAt time.Time
	LastCheckpointAt  time.Time
}

// RepoGroup is one top-level entry in the dispatch output.
type RepoGroup struct {
	FullName string
	Sections []Section
}

// Section groups bullets under a label (e.g., "CI & Tooling").
type Section struct {
	Label   string
	Bullets []Bullet
}

// Bullet is one line item in a section.
type Bullet struct {
	CheckpointID string
	Text         string
	Source       string // "cloud_analysis" | "local_summary" | "commit_message"
	Branch       string
	CreatedAt    time.Time
	Labels       []string
}

// Totals aggregates counts across the whole dispatch.
type Totals struct {
	Checkpoints         int
	UsedCheckpointCount int
	Branches            int
	FilesTouched        int
}

// Warnings reports per-classification counts of non-bullet-producing
// checkpoints.
type Warnings struct {
	AccessDeniedCount  int
	PendingCount       int
	FailedCount        int
	UnknownCount       int
	UncategorizedCount int
}

