package dispatch

import (
	_ "embed"
	"os"
	"strings"
)

//go:embed voices/neutral.md
var voiceNeutral string

//go:embed voices/marvin.md
var voiceMarvin string

// Voice is the resolved form of a --voice input.
type Voice struct {
	// Name is the preset name when IsPreset is true, otherwise empty.
	Name string
	// Text is the voice-guidance text sent to the LLM.
	Text string
	// IsPreset indicates whether the value matched a shipped preset.
	IsPreset bool
}

// presets is keyed by lowercase preset name.
var presets = map[string]string{
	"neutral": voiceNeutral,
	"marvin":  voiceMarvin,
}

// ResolveVoice applies the resolution chain to a raw --voice value:
//  1. If the value matches a built-in preset (case-insensitive), use it.
//  2. Else, if it resolves to a readable regular file, use the file contents.
//  3. Else, treat the value as a literal description.
//
// An empty value defaults to the "neutral" preset.
func ResolveVoice(value string) Voice {
	if value == "" {
		return Voice{Name: "neutral", Text: voiceNeutral, IsPreset: true}
	}
	if text, ok := presets[strings.ToLower(value)]; ok {
		return Voice{Name: strings.ToLower(value), Text: text, IsPreset: true}
	}
	if info, err := os.Stat(value); err == nil && !info.IsDir() {
		if b, err := os.ReadFile(value); err == nil {
			return Voice{Name: "", Text: string(b), IsPreset: false}
		}
	}
	return Voice{Name: "", Text: value, IsPreset: false}
}

// ListPresetNames returns the shipped preset names in stable order.
func ListPresetNames() []string {
	return []string{"neutral", "marvin"}
}

