package dispatch

import (
	"fmt"
	"regexp"
	"strconv"
	"strings"
	"time"
)

var (
	// goDurationPat matches compact durations like "7d", "6h", "2w" — a subset of
	// the Go duration grammar extended with "d" (days) and "w" (weeks).
	goDurationPat = regexp.MustCompile(`^(\d+)([smhdw])$`)

	// relativePat matches git-style phrases like "2 days ago" or "1 week ago".
	relativePat = regexp.MustCompile(`^(\d+)\s*(second|minute|hour|day|week|month)s?\s*ago$`)
)

// ParseSinceAtNow parses a --since value against a reference time. Accepts
// three forms: (a) compact Go-style duration with day/week extensions (e.g.
// "7d", "6h", "2w"); (b) git-style relative phrases (e.g. "2 days ago");
// (c) an ISO date "2006-01-02" or a full RFC3339 timestamp.
func ParseSinceAtNow(value string, now time.Time) (time.Time, error) {
	value = strings.TrimSpace(value)
	if value == "" {
		return time.Time{}, fmt.Errorf("empty --since value")
	}

	if m := goDurationPat.FindStringSubmatch(value); m != nil {
		n, err := strconv.ParseInt(m[1], 10, 64)
		if err != nil {
			return time.Time{}, fmt.Errorf("invalid --since count %q: %w", m[1], err)
		}
		unit := durationUnit(m[2])
		return now.Add(-time.Duration(n) * unit), nil
	}

	if m := relativePat.FindStringSubmatch(strings.ToLower(value)); m != nil {
		n, err := strconv.ParseInt(m[1], 10, 64)
		if err != nil {
			return time.Time{}, fmt.Errorf("invalid --since count %q: %w", m[1], err)
		}
		return now.Add(-time.Duration(n) * relativeUnit(m[2])), nil
	}

	if t, err := time.Parse(time.RFC3339, value); err == nil {
		return t, nil
	}
	if t, err := time.Parse("2006-01-02", value); err == nil {
		return t, nil
	}
	return time.Time{}, fmt.Errorf("unparseable --since: %q (accepts 7d, \"2 days ago\", 2026-04-09, or RFC3339)", value)
}

func durationUnit(suffix string) time.Duration {
	switch suffix {
	case "s":
		return time.Second
	case "m":
		return time.Minute
	case "h":
		return time.Hour
	case "d":
		return 24 * time.Hour
	case "w":
		return 7 * 24 * time.Hour
	default:
		return time.Second
	}
}

func relativeUnit(word string) time.Duration {
	switch word {
	case "second":
		return time.Second
	case "minute":
		return time.Minute
	case "hour":
		return time.Hour
	case "day":
		return 24 * time.Hour
	case "week":
		return 7 * 24 * time.Hour
	case "month":
		return 30 * 24 * time.Hour
	default:
		return time.Second
	}
}

// ParseBranches parses a --branches value. Empty → current branch only; "all"
// or "*" → all branches (branches slice is nil, allBranches=true); otherwise
// a comma-separated list of branch names.
func ParseBranches(value, currentBranch string) (branches []string, allBranches bool, err error) {
	trimmed := strings.TrimSpace(value)
	switch strings.ToLower(trimmed) {
	case "":
		if currentBranch == "" {
			return nil, false, fmt.Errorf("no branches specified and no current branch resolved")
		}
		return []string{currentBranch}, false, nil
	case "all", "*":
		return nil, true, nil
	}
	parts := strings.Split(trimmed, ",")
	out := make([]string, 0, len(parts))
	for _, p := range parts {
		p = strings.TrimSpace(p)
		if p != "" {
			out = append(out, p)
		}
	}
	if len(out) == 0 {
		return nil, false, fmt.Errorf("empty --branches list")
	}
	return out, false, nil
}

