// CreateDispatch POSTs to /api/v1/users/me/dispatches.
func (c *CloudClient) CreateDispatch(ctx context.Context, body CreateDispatchRequest) (*CreateDispatchResponse, error) {
	raw, err := json.Marshal(body)
	if err != nil {
		return nil, fmt.Errorf("encoding request: %w", err)
	}
	req, err := http.NewRequestWithContext(ctx, http.MethodPost, c.cfg.BaseURL+"/api/v1/users/me/dispatches", bytes.NewReader(raw))
	if err != nil {
		return nil, err
	}
	req.Header.Set("Content-Type", "application/json")
	if c.cfg.Token != "" {
		req.Header.Set("Authorization", "Bearer "+c.cfg.Token)
	}
	res, err := c.cfg.HTTP.Do(req)
	if err != nil {
		return nil, fmt.Errorf("dispatch request: %w", err)
	}
	defer func() { _ = res.Body.Close() }()

	switch {
	case res.StatusCode == 401 || res.StatusCode == 403:
		return nil, errors.New("login expired — run `entire login`")
	case res.StatusCode == 404:
		return nil, fmt.Errorf("dispatch server not available (404) — use --local")
	case res.StatusCode >= 500:
		snippet, _ := io.ReadAll(io.LimitReader(res.Body, 512))
		return nil, fmt.Errorf("server error %d: %s — try --local", res.StatusCode, string(snippet))
	}

	var out CreateDispatchResponse
	if err := json.NewDecoder(res.Body).Decode(&out); err != nil {
		return nil, fmt.Errorf("decoding response: %w", err)
	}
	return &out, nil
}

// FetchBatchAnalyses calls POST /api/v1/users/me/checkpoints/analyses/batch,
// paginating over chunks of up to DefaultBatchSize IDs.
func (c *CloudClient) FetchBatchAnalyses(ctx context.Context, repoFullName string, ids []string) (map[string]AnalysisStatus, error) {
	out := make(map[string]AnalysisStatus, len(ids))
	for start := 0; start < len(ids); start += DefaultBatchSize {
		end := start + DefaultBatchSize
		if end > len(ids) {
			end = len(ids)
		}
		chunk := ids[start:end]

		body, err := json.Marshal(map[string]any{
			"repoFullName":  repoFullName,
			"checkpointIds": chunk,
		})
		if err != nil {
			return nil, fmt.Errorf("encoding batch request: %w", err)
		}
		req, err := http.NewRequestWithContext(ctx, http.MethodPost, c.cfg.BaseURL+"/api/v1/users/me/checkpoints/analyses/batch", bytes.NewReader(body))
		if err != nil {
			return nil, err
		}
		req.Header.Set("Content-Type", "application/json")
		if c.cfg.Token != "" {
			req.Header.Set("Authorization", "Bearer "+c.cfg.Token)
		}
		res, err := c.cfg.HTTP.Do(req)
		if err != nil {
			return nil, fmt.Errorf("batch analyses request: %w", err)
		}

		if res.StatusCode == 401 || res.StatusCode == 403 {
			_ = res.Body.Close()
			return nil, errors.New("login expired — run `entire login`")
		}
		if res.StatusCode != 200 {
			snippet, _ := io.ReadAll(io.LimitReader(res.Body, 512))
			_ = res.Body.Close()
			return nil, fmt.Errorf("batch analyses: %d: %s", res.StatusCode, string(snippet))
		}

		var payload struct {
			Analyses map[string]AnalysisStatus `json:"analyses"`
		}
		if err := json.NewDecoder(res.Body).Decode(&payload); err != nil {
			_ = res.Body.Close()
			return nil, fmt.Errorf("decoding batch analyses: %w", err)
		}
		_ = res.Body.Close()
		for k, v := range payload.Analyses {
			out[k] = v
		}
	}
	return out, nil
}

