package dispatch

import (
	"testing"
	"time"
)

func cand(id string, opts ...func(*Candidate)) Candidate {
	c := Candidate{
		ID:           id,
		RepoFullName: "entireio/cli",
		Branch:       "main",
		CreatedAt:    time.Date(2026, 4, 14, 12, 0, 0, 0, time.UTC),
	}
	for _, o := range opts {
		o(&c)
	}
	return c
}

func withCommit(subject string) func(*Candidate) {
	return func(c *Candidate) { c.CommitSubject = subject }
}

func withLocalSummary(title string) func(*Candidate) {
	return func(c *Candidate) { c.LocalSummaryTitle = title }
}

func TestApplyFallbackChain_CloudComplete(t *testing.T) {
	t.Parallel()
	candidates := []Candidate{cand("a")}
	analyses := map[string]AnalysisStatus{"a": {Status: "complete", Summary: "Shipped login", Labels: []string{"Auth"}}}
	res := ApplyFallbackChain(candidates, analyses)
	if len(res.Used) != 1 {
		t.Fatalf("expected 1 used bullet, got %d", len(res.Used))
	}
	if res.Used[0].Source != "cloud_analysis" {
		t.Fatalf("expected cloud_analysis source, got %q", res.Used[0].Source)
	}
	if res.Used[0].Text != "Shipped login" {
		t.Fatalf("bad text: %q", res.Used[0].Text)
	}
	if got := res.Used[0].Labels; len(got) != 1 || got[0] != "Auth" {
		t.Fatalf("bad labels: %v", got)
	}
	if res.Warnings != (Warnings{}) {
		t.Fatalf("expected no warnings, got %+v", res.Warnings)
	}
}

func TestApplyFallbackChain_Pending(t *testing.T) {
	t.Parallel()
	candidates := []Candidate{cand("a")}
	analyses := map[string]AnalysisStatus{"a": {Status: "pending"}}
	res := ApplyFallbackChain(candidates, analyses)
	if len(res.Used) != 0 {
		t.Fatalf("expected 0 used, got %d", len(res.Used))
	}
	if res.Warnings.PendingCount != 1 {
		t.Fatalf("expected pending_count=1, got %+v", res.Warnings)
	}
}

func TestApplyFallbackChain_Generating(t *testing.T) {
	t.Parallel()
	res := ApplyFallbackChain([]Candidate{cand("a")}, map[string]AnalysisStatus{"a": {Status: "generating"}})
	if res.Warnings.PendingCount != 1 {
		t.Fatalf("generating should count toward pending, got %+v", res.Warnings)
	}
}

func TestApplyFallbackChain_Failed_FallsThroughToLocalSummary(t *testing.T) {
	t.Parallel()
	candidates := []Candidate{cand("a", withLocalSummary("Local summary title"), withCommit("commit subject"))}
	res := ApplyFallbackChain(candidates, map[string]AnalysisStatus{"a": {Status: "failed"}})
	if len(res.Used) != 1 {
		t.Fatalf("expected 1 used, got %d", len(res.Used))
	}
	if res.Used[0].Source != "local_summary" {
		t.Fatalf("expected local_summary source, got %q", res.Used[0].Source)
	}
	if res.Used[0].Text != "Local summary title" {
		t.Fatalf("bad text: %q", res.Used[0].Text)
	}
	if res.Warnings.FailedCount != 1 {
		t.Fatalf("expected failed_count=1, got %+v", res.Warnings)
	}
}

func TestApplyFallbackChain_NotVisible_FallsThroughToCommit(t *testing.T) {
	t.Parallel()
	candidates := []Candidate{cand("a", withCommit("Commit subject"))}
	res := ApplyFallbackChain(candidates, map[string]AnalysisStatus{"a": {Status: "not_visible"}})
	if len(res.Used) != 1 {
		t.Fatalf("expected 1 used, got %d", len(res.Used))
	}
	if res.Used[0].Source != "commit_message" {
		t.Fatalf("expected commit_message source, got %q", res.Used[0].Source)
	}
	if res.Warnings.AccessDeniedCount != 1 {
		t.Fatalf("expected access_denied_count=1, got %+v", res.Warnings)
	}
}

func TestApplyFallbackChain_Unknown_WithCommitFallback(t *testing.T) {
	t.Parallel()
	candidates := []Candidate{cand("a", withCommit("Commit"))}
	res := ApplyFallbackChain(candidates, map[string]AnalysisStatus{"a": {Status: "unknown"}})
	if res.Used[0].Source != "commit_message" {
		t.Fatalf("expected commit_message source, got %q", res.Used[0].Source)
	}
	if res.Warnings.UnknownCount != 1 {
		t.Fatalf("expected unknown_count=1, got %+v", res.Warnings)
	}
}

func TestApplyFallbackChain_Uncategorized(t *testing.T) {
	t.Parallel()
	candidates := []Candidate{cand("a")}
	res := ApplyFallbackChain(candidates, map[string]AnalysisStatus{"a": {Status: "unknown"}})
	if len(res.Used) != 0 {
		t.Fatalf("expected 0 used, got %d", len(res.Used))
	}
	if res.Warnings.UncategorizedCount != 1 {
		t.Fatalf("expected uncategorized_count=1, got %+v", res.Warnings)
	}
	if res.Warnings.UnknownCount != 1 {
		t.Fatalf("expected unknown_count=1 (still surfaced), got %+v", res.Warnings)
	}
}

func TestApplyFallbackChain_NoAnalysisEntry_TreatedAsUnknown(t *testing.T) {
	t.Parallel()
	candidates := []Candidate{cand("a", withCommit("Commit"))}
	res := ApplyFallbackChain(candidates, map[string]AnalysisStatus{})
	if res.Used[0].Source != "commit_message" {
		t.Fatalf("expected commit_message fallback, got %q", res.Used[0].Source)
	}
	if res.Warnings.UnknownCount != 1 {
		t.Fatalf("missing analysis entry should count as unknown, got %+v", res.Warnings)
	}
}

func REDACTED(t *testing.T) {
	t.Parallel()
	candidates := []Candidate{cand("a", withLocalSummary("Local"), withCommit("Commit"))}
	res := ApplyFallbackChain(candidates, map[string]AnalysisStatus{"a": {Status: "unknown"}})
	if res.Used[0].Text != "Local" {
		t.Fatalf("expected local summary preferred over commit, got %q", res.Used[0].Text)
	}
}

package dispatch

import "time"

// Candidate is a checkpoint that is eligible to produce a bullet. Collected
// from local git state (local mode) or from the server's enumeration.
type Candidate struct {
	ID                string
	RepoFullName      string
	Branch            string
	CreatedAt         time.Time
	CommitSubject     string // empty if the checkpoint has no associated commit
	LocalSummaryTitle string // empty if summarization is disabled or no title exists
	FilesTouched      []string
}

// UsedBullet is a bullet that passed the fallback chain.
type UsedBullet struct {
	ID           string
	RepoFullName string
	Branch       string
	CreatedAt    time.Time
	Source       string // "cloud_analysis" | "local_summary" | "commit_message"
	Text         string
	Labels       []string
	FilesTouched []string
}

// FallbackResult combines the bullets produced by the chain with the
// classification warnings.
type FallbackResult struct {
	Used     []UsedBullet
	Warnings Warnings
}

// ApplyFallbackChain resolves each candidate into at most one used bullet,
// following the three-step chain specified in the CLI spec:
//  1. Cloud analysis (status: complete) — use summary + labels.
//  2. Local summarize title (if available).
//  3. Commit message subject (if available).
//
// Non-complete cloud statuses increment the corresponding warning counter
// but still fall through to local data sources, except pending/generating
// which skip entirely (the user will see the bullet appear once it completes
// on the next re-run).
func ApplyFallbackChain(candidates []Candidate, analyses map[string]AnalysisStatus) FallbackResult {
	out := FallbackResult{Used: make([]UsedBullet, 0, len(candidates))}

	for _, c := range candidates {
		a, hadEntry := analyses[c.ID]
		status := a.Status
		if !hadEntry || status == "" {
			status = "unknown"
		}

		switch status {
		case "complete":
			out.Used = append(out.Used, UsedBullet{
				ID:           c.ID,
				RepoFullName: c.RepoFullName,
				Branch:       c.Branch,
				CreatedAt:    c.CreatedAt,
				Source:       "cloud_analysis",
				Text:         a.Summary,
				Labels:       append([]string(nil), a.Labels...),
				FilesTouched: c.FilesTouched,
			})
			continue
		case "pending", "generating":
			out.Warnings.PendingCount++
			continue
		case "failed":
			out.Warnings.FailedCount++
		case "not_visible":
			out.Warnings.AccessDeniedCount++
		case "unknown":
			out.Warnings.UnknownCount++
		default:
			// Unknown-to-us status — surface as unknown_count rather than
			// silently dropping.
			out.Warnings.UnknownCount++
		}

		// Fall through to local fallback sources.
		if c.LocalSummaryTitle != "" {
			out.Used = append(out.Used, UsedBullet{
				ID:           c.ID,
				RepoFullName: c.RepoFullName,
				Branch:       c.Branch,
				CreatedAt:    c.CreatedAt,
				Source:       "local_summary",
				Text:         c.LocalSummaryTitle,
				FilesTouched: c.FilesTouched,
			})
			continue
		}
		if c.CommitSubject != "" {
			out.Used = append(out.Used, UsedBullet{
				ID:           c.ID,
				RepoFullName: c.RepoFullName,
				Branch:       c.Branch,
				CreatedAt:    c.CreatedAt,
				Source:       "commit_message",
				Text:         c.CommitSubject,
				FilesTouched: c.FilesTouched,
			})
			continue
		}
		out.Warnings.UncategorizedCount++
	}

	return out
}

