import (
	"context"
	"errors"
	"fmt"
	"os"
	"sort"
	"time"

	"github.com/entireio/cli/cmd/entire/cli/auth"
	"github.com/entireio/cli/cmd/entire/cli/paths"
	"github.com/entireio/cli/cmd/entire/cli/search"
	"github.com/entireio/cli/cmd/entire/cli/strategy"
	"github.com/go-git/go-git/v6"
)

// cloudAnalysesFetcher abstracts the batch-analyses call so runLocal can be
// tested with a fake client.
type cloudAnalysesFetcher interface {
	FetchBatchAnalyses(ctx context.Context, repoFullName string, ids []string) (map[string]AnalysisStatus, error)
}

// candidateSource abstracts local checkpoint enumeration so buildLocalDispatch
// can be exercised in tests without needing a seeded git repo.
type candidateSource interface {
	ListCandidates(ctx context.Context) ([]Candidate, error)
}

// runLocal is the production entry point for --local mode. It wires together
// real dependencies (git remote, strategy.ListCheckpoints, the cloud client)
// and delegates the actual assembly to buildLocalDispatch.
func runLocal(ctx context.Context, opts Options) (*Dispatch, error) {
	// Resolve repo root + remote.
	repoRoot, err := paths.WorktreeRoot(ctx)
	if err != nil {
		return nil, fmt.Errorf("not in a git repository: %w", err)
	}
	repoFullName, err := resolveRepoFullNameAt(repoRoot)
	if err != nil {
		return nil, err
	}

	// Resolve the user's token for the batch-analyses call.
	token, err := auth.LookupCurrentToken()
	if err != nil {
		return nil, fmt.Errorf("reading credentials: %w", err)
	}
	if token == "" {
		return nil, errors.New("dispatch requires login — run `entire login`")
	}

	cloud := NewCloudClient(CloudConfig{
		BaseURL: cloudBaseURL(),
		Token:   token,
	})

	src := strategyCandidateSource{repoFullName: repoFullName}
	return buildLocalDispatch(ctx, opts, src, cloud)
}

// strategyCandidateSource is the production candidateSource, backed by
// strategy.ListCheckpoints.
type strategyCandidateSource struct {
	repoFullName string
}

// ListCandidates returns all locally-indexed checkpoints as bullet candidates.
// NOTE: v1 sets Branch and CommitSubject and LocalSummaryTitle to empty —
// richer local fallback data can be added by enriching CheckpointInfo in a
// follow-up without changing this function's signature.
func (s strategyCandidateSource) ListCandidates(ctx context.Context) ([]Candidate, error) {
	infos, err := strategy.ListCheckpoints(ctx)
	if err != nil {
		return nil, fmt.Errorf("listing checkpoints: %w", err)
	}
	out := make([]Candidate, 0, len(infos))
	for _, info := range infos {
		out = append(out, Candidate{
			ID:           string(info.CheckpointID),
			RepoFullName: s.repoFullName,
			CreatedAt:    info.CreatedAt,
			FilesTouched: info.FilesTouched,
		})
	}
	return out, nil
}

// buildLocalDispatch is the pure-ish core of local mode: candidates come in,
// a Dispatch comes out. Splitting this from runLocal makes it unit-testable.
func buildLocalDispatch(ctx context.Context, opts Options, src candidateSource, cloud cloudAnalysesFetcher) (*Dispatch, error) {
	now := time.Now().UTC()
	since, err := ParseSinceAtNow(opts.Since, now)
	if err != nil {
		return nil, err
	}
	normalizedSince, normalizedUntil := NormalizeWindow(since, now)

	allCandidates, err := src.ListCandidates(ctx)
	if err != nil {
		return nil, err
	}

	candidates := filterCandidatesByWindow(allCandidates, normalizedSince, normalizedUntil)

	// Group IDs by repo for batch calls.
	byRepo := make(map[string][]string)
	for _, c := range candidates {
		byRepo[c.RepoFullName] = append(byRepo[c.RepoFullName], c.ID)
	}
	analyses := make(map[string]AnalysisStatus, len(candidates))
	for repo, ids := range byRepo {
		m, err := cloud.FetchBatchAnalyses(ctx, repo, ids)
		if err != nil {
			return nil, err
		}
		for k, v := range m {
			analyses[k] = v
		}
	}

	result := ApplyFallbackChain(candidates, analyses)
	groups := groupBulletsByRepo(result.Used)

	return &Dispatch{
		Repos: groups,
		Window: Window{
			NormalizedSince:   normalizedSince,
			NormalizedUntil:   normalizedUntil,
			FirstCheckpointAt: firstCheckpointAt(result.Used),
			LastCheckpointAt:  lastCheckpointAt(result.Used),
		},
		Totals: Totals{
			Checkpoints:         len(candidates),
			UsedCheckpointCount: len(result.Used),
			Branches:            countDistinctBranches(candidates),
			FilesTouched:        countDistinctFiles(candidates),
		},
		Warnings:          result.Warnings,
		CoveredRepos:      distinctRepos(candidates),
		RequestedGenerate: opts.Generate,
		DryRun:            opts.DryRun,
	}, nil
}

// NormalizeWindow applies floor/ceil-to-minute per the dispatch spec.
func NormalizeWindow(since, until time.Time) (time.Time, time.Time) {
	floored := since.Truncate(time.Minute)
	ceiled := until.Truncate(time.Minute)
	if !until.Equal(ceiled) {
		ceiled = ceiled.Add(time.Minute)
	}
	return floored, ceiled
}

func filterCandidatesByWindow(candidates []Candidate, since, until time.Time) []Candidate {
	out := make([]Candidate, 0, len(candidates))
	for _, c := range candidates {
		if !c.CreatedAt.Before(since) && c.CreatedAt.Before(until) {
			out = append(out, c)
		}
	}
	return out
}

// groupBulletsByRepo produces the RepoGroup shape from a flat list of used
// bullets. Sections are grouped by first label; unlabeled bullets go into an
// "Updates" section per repo.
func groupBulletsByRepo(used []UsedBullet) []RepoGroup {
	byRepo := make(map[string]map[string][]Bullet)
	repoOrder := []string{}
	for _, u := range used {
		label := "Updates"
		if len(u.Labels) > 0 {
			label = u.Labels[0]
		}
		if _, ok := byRepo[u.RepoFullName]; !ok {
			byRepo[u.RepoFullName] = map[string][]Bullet{}
			repoOrder = append(repoOrder, u.RepoFullName)
		}
		byRepo[u.RepoFullName][label] = append(byRepo[u.RepoFullName][label], Bullet{
			CheckpointID: u.ID,
			Text:         u.Text,
			Source:       u.Source,
			Branch:       u.Branch,
			CreatedAt:    u.CreatedAt,
			Labels:       u.Labels,
		})
	}

	groups := make([]RepoGroup, 0, len(repoOrder))
	sort.Strings(repoOrder)
	for _, repo := range repoOrder {
		sections := byRepo[repo]
		labels := make([]string, 0, len(sections))
		for l := range sections {
			labels = append(labels, l)
		}
		sort.Strings(labels)
		grp := RepoGroup{FullName: repo}
		for _, l := range labels {
			grp.Sections = append(grp.Sections, Section{Label: l, Bullets: sections[l]})
		}
		groups = append(groups, grp)
	}
	return groups
}

func firstCheckpointAt(used []UsedBullet) time.Time {
	if len(used) == 0 {
		return time.Time{}
	}
	t := used[0].CreatedAt
	for _, u := range used[1:] {
		if u.CreatedAt.Before(t) {
			t = u.CreatedAt
		}
	}
	return t
}

func lastCheckpointAt(used []UsedBullet) time.Time {
	if len(used) == 0 {
		return time.Time{}
	}
	t := used[0].CreatedAt
	for _, u := range used[1:] {
		if u.CreatedAt.After(t) {
			t = u.CreatedAt
		}
	}
	return t
}

func countDistinctBranches(candidates []Candidate) int {
	set := make(map[string]struct{})
	for _, c := range candidates {
		if c.Branch != "" {
			set[c.Branch] = struct{}{}
		}
	}
	return len(set)
}

func countDistinctFiles(candidates []Candidate) int {
	set := make(map[string]struct{})
	for _, c := range candidates {
		for _, f := range c.FilesTouched {
			set[f] = struct{}{}
		}
	}
	return len(set)
}

func distinctRepos(candidates []Candidate) []string {
	set := make(map[string]struct{})
	for _, c := range candidates {
		if c.RepoFullName != "" {
			set[c.RepoFullName] = struct{}{}
		}
	}
	out := make([]string, 0, len(set))
	for r := range set {
		out = append(out, r)
	}
	sort.Strings(out)
	return out
}

// cloudBaseURL returns the dispatch API base URL, overridable via the
// ENTIRE_API_BASE_URL environment variable (primarily for tests).
func cloudBaseURL() string {
	if v := os.Getenv("ENTIRE_API_BASE_URL"); v != "" {
		return v
	}
	return DefaultBaseURL
}

// resolveRepoFullNameAt opens the git repo at repoRoot and returns its
// origin's "owner/repo" full name.
func resolveRepoFullNameAt(repoRoot string) (string, error) {
	r, err := git.PlainOpen(repoRoot)
	if err != nil {
		return "", fmt.Errorf("opening repository: %w", err)
	}
	remote, err := r.Remote("origin")
	if err != nil {
		return "", fmt.Errorf("resolving origin remote: %w", err)
	}
	urls := remote.Config().URLs
	if len(urls) == 0 {
		return "", errors.New("origin remote has no URL")
	}
	owner, repo, err := search.ParseGitHubRemote(urls[0])
	if err != nil {
		return "", fmt.Errorf("parsing remote URL: %w", err)
	}
	return fmt.Sprintf("%s/%s", owner, repo), nil
}

