func TestBuildLocalDispatch_CountsAndGrouping(t *testing.T) {
	t.Parallel()
	now := time.Now().UTC()
	// Three candidates inside the window, one outside.
	candidates := []Candidate{
		{ID: "a", RepoFullName: "entireio/cli", CreatedAt: now.Add(-3 * 24 * time.Hour)},
		{ID: "b", RepoFullName: "entireio/cli", CreatedAt: now.Add(-2 * 24 * time.Hour)},
		{ID: "c", RepoFullName: "entireio/cli", CreatedAt: now.Add(-1 * 24 * time.Hour)},
		{ID: "d", RepoFullName: "entireio/cli", CreatedAt: now.Add(-30 * 24 * time.Hour)}, // outside 7d window
	}
	analyses := map[string]AnalysisStatus{
		"a": {Status: "complete", Summary: "A summary", Labels: []string{"CI"}},
		"b": {Status: "complete", Summary: "B summary", Labels: []string{"Bugs"}},
		"c": {Status: "pending"},
	}
	opts := Options{Mode: ModeLocal, Since: "7d", Format: "text"}

	got, err := buildLocalDispatch(context.Background(), opts, fakeCandidateSource{candidates: candidates}, fakeCloud{analyses: analyses})
	if err != nil {
		t.Fatal(err)
	}
	if got.Totals.Checkpoints != 3 {
		t.Fatalf("expected 3 candidates in window, got %d", got.Totals.Checkpoints)
	}
	if got.Totals.UsedCheckpointCount != 2 {
		t.Fatalf("expected 2 used, got %d", got.Totals.UsedCheckpointCount)
	}
	if got.Warnings.PendingCount != 1 {
		t.Fatalf("expected 1 pending, got %+v", got.Warnings)
	}
	if len(got.Repos) != 1 {
		t.Fatalf("expected 1 repo group, got %d", len(got.Repos))
	}
	// Two labels: "Bugs" and "CI" — sorted alphabetically.
	if len(got.Repos[0].Sections) != 2 {
		t.Fatalf("expected 2 sections, got %d", len(got.Repos[0].Sections))
	}
	if got.Repos[0].Sections[0].Label != "Bugs" {
		t.Fatalf("expected first section Bugs, got %q", got.Repos[0].Sections[0].Label)
	}
}

