func TestNormalizeWindow_FloorCeil(t *testing.T) {
	t.Parallel()
	since := time.Date(2026, 4, 16, 14, 32, 47, 500_000_000, time.UTC)
	until := time.Date(2026, 4, 16, 14, 33, 12, 1_000_000, time.UTC)
	ns, nu := NormalizeWindow(since, until)
	if ns != time.Date(2026, 4, 16, 14, 32, 0, 0, time.UTC) {
		t.Fatalf("floor failed: got %v", ns)
	}
	if nu != time.Date(2026, 4, 16, 14, 34, 0, 0, time.UTC) {
		t.Fatalf("ceil failed: got %v", nu)
	}
}

func TestNormalizeWindow_AlreadyOnMinute(t *testing.T) {
	t.Parallel()
	since := time.Date(2026, 4, 16, 14, 32, 0, 0, time.UTC)
	until := time.Date(2026, 4, 16, 14, 34, 0, 0, time.UTC)
	ns, nu := NormalizeWindow(since, until)
	if ns != since {
		t.Fatalf("already-aligned since should be unchanged: %v", ns)
	}
	if nu != until {
		t.Fatalf("already-aligned until should be unchanged: %v", nu)
	}
}

package dispatch

import (
	"context"
	"errors"
	"fmt"
	"time"

	"github.com/entireio/cli/cmd/entire/cli/auth"
	"github.com/entireio/cli/cmd/entire/cli/paths"
)

// dispatchCreator abstracts the POST /dispatches call for testability.
type dispatchCreator interface {
	CreateDispatch(ctx context.Context, body CreateDispatchRequest) (*CreateDispatchResponse, error)
}

// runServer is the production --local-off path: wires the git-remote resolver,
// auth token, and CloudClient, then delegates to callServerDispatch.
func runServer(ctx context.Context, opts Options) (*Dispatch, error) {
	token, err := auth.LookupCurrentToken()
	if err != nil {
		return nil, fmt.Errorf("reading credentials: %w", err)
	}
	if token == "" {
		return nil, errors.New("dispatch requires login — run `entire login`")
	}

	var repoFullName string
	if opts.Org == "" {
		repoRoot, err := paths.WorktreeRoot(ctx)
		if err != nil {
			return nil, fmt.Errorf("not in a git repository: %w", err)
		}
		repoFullName, err = resolveRepoFullNameAt(repoRoot)
		if err != nil {
			return nil, err
		}
	}

	cloud := NewCloudClient(CloudConfig{BaseURL: cloudBaseURL(), Token: token})
	return callServerDispatch(ctx, opts, repoFullName, cloud)
}

// callServerDispatch is the unit-testable core of server mode: it constructs
// the request body, calls the injected dispatchCreator, and maps the response
// into the public Dispatch type.
func callServerDispatch(ctx context.Context, opts Options, repoFullName string, cloud dispatchCreator) (*Dispatch, error) {
	now := time.Now().UTC()
	since, err := ParseSinceAtNow(opts.Since, now)
	if err != nil {
		return nil, err
	}

	var branches any
	if opts.AllBranches {
		branches = "all"
	} else {
		branches = opts.Branches
	}

	req := CreateDispatchRequest{
		Repo:     repoFullName,
		Org:      opts.Org,
		Since:    since.Format(time.RFC3339),
		Until:    now.Format(time.RFC3339),
		Branches: branches,
		Generate: opts.Generate,
		Voice:    opts.Voice,
		DryRun:   opts.DryRun,
	}

	res, err := cloud.CreateDispatch(ctx, req)
	if err != nil {
		return nil, err
	}
	return apiToDispatch(res), nil
}

// apiToDispatch flattens the server response into the CLI's public Dispatch
// shape, normalizing timestamps and carrying the DryRun / RequestedGenerate
// flags.
func apiToDispatch(res *CreateDispatchResponse) *Dispatch {
	d := &Dispatch{
		ID:              res.ID,
		FingerprintHash: res.FingerprintHash,
		WebURL:          res.WebURL,
		CoveredRepos:    res.CoveredRepos,
		GeneratedText:   res.GeneratedText,
		DryRun:          res.DryRun,
		Deduped:         res.Deduped,
		Generated:       res.GeneratedText != "",
		Totals: Totals{
			Checkpoints:         res.Totals.Checkpoints,
			UsedCheckpointCount: res.Totals.UsedCheckpointCount,
			Branches:            res.Totals.Branches,
			FilesTouched:        res.Totals.FilesTouched,
		},
		Warnings: Warnings{
			AccessDeniedCount:  res.Warnings.AccessDeniedCount,
			PendingCount:       res.Warnings.PendingCount,
			FailedCount:        res.Warnings.FailedCount,
			UnknownCount:       res.Warnings.UnknownCount,
			UncategorizedCount: res.Warnings.UncategorizedCount,
		},
	}
	if res.RequestedGenerate != nil {
		d.RequestedGenerate = *res.RequestedGenerate
	}
	d.Window = apiWindowToWindow(res.Window)
	d.Repos = apiReposToRepos(res.Repos)
	return d
}

func apiWindowToWindow(w APIWindow) Window {
	out := Window{}
	if t, err := time.Parse(time.RFC3339, w.NormalizedSince); err == nil {
		out.NormalizedSince = t
	}
	if t, err := time.Parse(time.RFC3339, w.NormalizedUntil); err == nil {
		out.NormalizedUntil = t
	}
	if w.FirstCheckpointCreatedAt != "" {
		if t, err := time.Parse(time.RFC3339, w.FirstCheckpointCreatedAt); err == nil {
			out.FirstCheckpointAt = t
		}
	}
	if w.LastCheckpointCreatedAt != "" {
		if t, err := time.Parse(time.RFC3339, w.LastCheckpointCreatedAt); err == nil {
			out.LastCheckpointAt = t
		}
	}
	return out
}

func apiReposToRepos(apiRepos []APIRepo) []RepoGroup {
	out := make([]RepoGroup, 0, len(apiRepos))
	for _, r := range apiRepos {
		grp := RepoGroup{FullName: r.FullName}
		for _, s := range r.Sections {
			section := Section{Label: s.Label}
			for _, b := range s.Bullets {
				bullet := Bullet{
					CheckpointID: b.CheckpointID,
					Text:         b.Text,
					Source:       b.Source,
					Branch:       b.Branch,
					Labels:       b.Labels,
				}
				if b.CreatedAt != "" {
					if t, err := time.Parse(time.RFC3339, b.CreatedAt); err == nil {
						bullet.CreatedAt = t
					}
				}
				section.Bullets = append(section.Bullets, bullet)
			}
			grp.Sections = append(grp.Sections, section)
		}
		out = append(out, grp)
	}
	return out
}

