func TestCallServerDispatch_HappyPath(t *testing.T) {
	t.Parallel()
	cloud := &fakeDispatchCreator{res: &CreateDispatchResponse{
		ID:              "dsp_1",
		Status:          "complete",
		FingerprintHash: "fp",
		Deduped:         false,
		WebURL:          "https://entire.io/dispatches/dsp_1",
		GeneratedText:   "Beep boop",
		Totals:          APITotals{Checkpoints: 5, UsedCheckpointCount: 3, Branches: 1, FilesTouched: 7},
		Repos: []APIRepo{{
			FullName: "entireio/cli",
			Sections: []APISection{{Label: "CI", Bullets: []APIBullet{{CheckpointID: "x", Text: "fix", Source: "cloud_analysis"}}}},
		}},
	}}

	opts := Options{Since: "7d", Branches: []string{"main"}, Generate: true, Voice: "neutral"}
	got, err := callServerDispatch(context.Background(), opts, "entireio/cli", cloud)
	if err != nil {
		t.Fatal(err)
	}
	if got.ID != "dsp_1" {
