	}
	if got.GeneratedText != "Beep boop" {
		t.Fatalf("bad generated text: %q", got.GeneratedText)
	}
	if !got.Generated {
		t.Fatal("Generated flag should be true when text is present")
	}
	if got.Totals.Checkpoints != 5 {
		t.Fatalf("bad totals: %+v", got.Totals)
	}
	if len(got.Repos) != 1 || got.Repos[0].FullName != "entireio/cli" {
