package dispatch

import (
	"encoding/json"
	"fmt"
	"sort"
	"strings"
	"time"
)

// RenderText produces the default plain-text dispatch output.
func RenderText(d *Dispatch) string {
	var b strings.Builder

	if d.DryRun {
		b.WriteString("entire dispatch --dry-run  ")
	} else if d.Generated {
		b.WriteString("entire dispatch --generate  ")
	} else {
		b.WriteString("entire dispatch  ")
	}
	fmt.Fprintf(&b, "(%s)\n\n", describeWindow(d.Window))

	if d.Generated && d.GeneratedText != "" {
		b.WriteString(d.GeneratedText)
		b.WriteString("\n\n")
	} else {
		for _, repo := range d.Repos {
			fmt.Fprintf(&b, "%s\n", repo.FullName)
			for _, section := range repo.Sections {
				fmt.Fprintf(&b, "  %s\n", section.Label)
				for _, bullet := range section.Bullets {
					fmt.Fprintf(&b, "    • %s\n", bullet.Text)
				}
				b.WriteString("\n")
			}
		}
	}

	fmt.Fprintf(&b, "%d checkpoints", d.Totals.Checkpoints)
	if d.Totals.Branches > 0 {
		fmt.Fprintf(&b, " · %d branches", d.Totals.Branches)
	}
	if d.Totals.FilesTouched > 0 {
		fmt.Fprintf(&b, " · %d files touched", d.Totals.FilesTouched)
	}
	b.WriteString("\n")

	writeWarningsText(&b, d.Warnings)

	if d.WebURL != "" {
		fmt.Fprintf(&b, "\nView: %s\n", d.WebURL)
	}
	return b.String()
}

// RenderMarkdown produces the pure-markdown variant — suitable for pasting
// into docs, blog posts, or markdown-rendered chat tools.
func RenderMarkdown(d *Dispatch) string {
	var b strings.Builder

	b.WriteString("# entire dispatch\n\n")
	fmt.Fprintf(&b, "_%s_\n\n", describeWindow(d.Window))

	if d.Generated && d.GeneratedText != "" {
		b.WriteString(d.GeneratedText)
		b.WriteString("\n\n")
	} else {
		for _, repo := range d.Repos {
			fmt.Fprintf(&b, "## %s\n\n", repo.FullName)
			for _, section := range repo.Sections {
				fmt.Fprintf(&b, "### %s\n\n", section.Label)
				for _, bullet := range section.Bullets {
					fmt.Fprintf(&b, "- %s\n", bullet.Text)
				}
				b.WriteString("\n")
			}
		}
	}

	b.WriteString("---\n\n")
	fmt.Fprintf(&b, "_%d checkpoints", d.Totals.Checkpoints)
	if d.Totals.Branches > 0 {
		fmt.Fprintf(&b, " · %d branches", d.Totals.Branches)
	}
	if d.Totals.FilesTouched > 0 {
		fmt.Fprintf(&b, " · %d files touched", d.Totals.FilesTouched)
	}
	b.WriteString("_\n")

	writeWarningsMarkdown(&b, d.Warnings)

	if d.WebURL != "" {
		fmt.Fprintf(&b, "\nView: <%s>\n", d.WebURL)
	}
	return b.String()
}

// RenderJSON produces the machine-readable variant used by --format json.
func RenderJSON(d *Dispatch) ([]byte, error) {
	out := map[string]any{
		"generated_at": time.Now().UTC().Format(time.RFC3339),
		"window": map[string]any{
			"normalized_since":            formatOrEmpty(d.Window.NormalizedSince),
			"normalized_until":            formatOrEmpty(d.Window.NormalizedUntil),
			"first_checkpoint_created_at": formatOrEmpty(d.Window.FirstCheckpointAt),
			"last_checkpoint_created_at":  formatOrEmpty(d.Window.LastCheckpointAt),
		},
		"repos":  toJSONRepos(d.Repos),
		"totals": d.Totals,
		"warnings": map[string]int{
			"access_denied_count":  d.Warnings.AccessDeniedCount,
			"pending_count":        d.Warnings.PendingCount,
			"failed_count":         d.Warnings.FailedCount,
			"unknown_count":        d.Warnings.UnknownCount,
			"uncategorized_count":  d.Warnings.UncategorizedCount,
		},
	}
	if d.ID != "" {
		out["id"] = d.ID
	}
	if d.FingerprintHash != "" {
		out["fingerprint_hash"] = d.FingerprintHash
	}
	if d.WebURL != "" {
		out["web_url"] = d.WebURL
	}
	if d.CoveredRepos != nil {
		out["covered_repos"] = d.CoveredRepos
	}
	if d.Generated && d.GeneratedText != "" {
		out["generated_text"] = d.GeneratedText
	}
	if d.DryRun {
		out["dry_run"] = true
		out["requested_generate"] = d.RequestedGenerate
	}
	if d.Deduped {
		out["deduped"] = true
	}
	return json.MarshalIndent(out, "", "  ")
}

func writeWarningsText(b *strings.Builder, w Warnings) {
	for _, line := range warningLines(w, "⚠ ", "⏳ ", "✕ ", "ℹ ") {
		fmt.Fprintf(b, "%s\n", line)
	}
}

func writeWarningsMarkdown(b *strings.Builder, w Warnings) {
	for _, line := range warningLines(w, "", "", "", "") {
		fmt.Fprintf(b, "\n_%s_\n", line)
	}
}

// warningLines returns non-empty human-readable warning lines in a stable
// order. Passed prefixes are attached per-class (text mode uses emoji, markdown
// uses plain text).
func warningLines(w Warnings, accessPrefix, pendingPrefix, failedPrefix, unknownPrefix string) []string {
	var out []string
	if w.AccessDeniedCount > 0 {
		out = append(out, fmt.Sprintf("%s%d checkpoints you no longer have access to", accessPrefix, w.AccessDeniedCount))
	}
	if w.PendingCount > 0 {
		out = append(out, fmt.Sprintf("%s%d checkpoints still being analyzed (retry in a minute or use --wait)", pendingPrefix, w.PendingCount))
	}
	if w.FailedCount > 0 {
		out = append(out, fmt.Sprintf("%s%d checkpoints failed analysis on the server", failedPrefix, w.FailedCount))
	}
	if w.UnknownCount > 0 {
		out = append(out, fmt.Sprintf("%s%d checkpoints not known to the server", unknownPrefix, w.UnknownCount))
	}
	if w.UncategorizedCount > 0 {
		out = append(out, fmt.Sprintf("%d uncategorized checkpoints skipped", w.UncategorizedCount))
	}
	return out
}

func describeWindow(w Window) string {
	if w.NormalizedSince.IsZero() || w.NormalizedUntil.IsZero() {
		return "window unknown"
	}
	return fmt.Sprintf("%s — %s",
		w.NormalizedSince.Format("Jan 2"),
		w.NormalizedUntil.Format("Jan 2"),
	)
}

func formatOrEmpty(t time.Time) string {
	if t.IsZero() {
		return ""
	}
	return t.UTC().Format(time.RFC3339)
}

func toJSONRepos(repos []RepoGroup) []map[string]any {
	out := make([]map[string]any, 0, len(repos))
	for _, r := range repos {
		sections := make([]map[string]any, 0, len(r.Sections))
		for _, s := range r.Sections {
			bullets := make([]map[string]any, 0, len(s.Bullets))
			for _, b := range s.Bullets {
				bm := map[string]any{
					"checkpoint_id": b.CheckpointID,
					"text":          b.Text,
					"source":        b.Source,
					"branch":        b.Branch,
					"created_at":    formatOrEmpty(b.CreatedAt),
					"labels":        emptyStringSlice(b.Labels),
				}
				bullets = append(bullets, bm)
			}
			// Sort labels within the section list output for determinism.
			sort.SliceStable(bullets, func(i, j int) bool {
				return fmt.Sprint(bullets[i]["checkpoint_id"]) < fmt.Sprint(bullets[j]["checkpoint_id"])
			})
			sections = append(sections, map[string]any{
				"label":   s.Label,
				"bullets": bullets,
			})
		}
		out = append(out, map[string]any{
			"full_name": r.FullName,
			"sections":  sections,
		})
	}
	return out
}

func emptyStringSlice(s []string) []string {
	if s == nil {
		return []string{}
	}
	return s
}

