package dispatch

import (
	"context"
	"errors"
	"fmt"
	"strings"

	"github.com/entireio/cli/cmd/entire/cli/agent"
	"github.com/entireio/cli/cmd/entire/cli/agent/claudecode"
)

// TextGenerator is the minimal interface the local --generate path needs.
// It matches agent.TextGenerator's GenerateText signature so the real
// Claude Code text generator is a drop-in.
type textGenerator interface {
	GenerateText(ctx context.Context, prompt string, model string) (string, error)
}

// defaultTextGeneratorFactory lets tests swap in a stub.
var defaultTextGeneratorFactory = func() (textGenerator, error) {
	gen, ok := agent.AsTextGenerator(claudecode.NewClaudeCodeAgent())
	if !ok {
		return nil, errors.New("local --generate requires the Claude Code CLI; install it or use --local without --generate")
	}
	return gen, nil
}

// GenerateLocally synthesizes a voice-shaped dispatch from a bullet list using
// the user's configured LLM. It's the --local --generate path.
func GenerateLocally(ctx context.Context, bullets []UsedBullet, voice Voice, gen textGenerator) (string, error) {
	if gen == nil {
		var err error
		gen, err = defaultTextGeneratorFactory()
		if err != nil {
			return "", err
		}
	}
	if len(bullets) == 0 {
		return "", errors.New("no bullets to synthesize")
	}
	prompt := buildGeneratePrompt(bullets, voice)
	text, err := gen.GenerateText(ctx, prompt, "sonnet")
	if err != nil {
		return "", fmt.Errorf("generating dispatch: %w", err)
	}
	return strings.TrimSpace(text), nil
}

func buildGeneratePrompt(bullets []UsedBullet, voice Voice) string {
	var b strings.Builder
	b.WriteString("You are composing a dispatch from bullet points about recent work.\n\n")
	b.WriteString("## Voice\n")
	b.WriteString(voice.Text)
	b.WriteString("\n\n## Rules\n")
	b.WriteString("- Group bullets into themed sections with headings.\n")
	b.WriteString("- Preserve the factual content of each bullet.\n")
	b.WriteString("- Never invent product details that aren't in the bullets.\n")
	b.WriteString("- Output markdown, ready to paste into a doc or blog post.\n\n")
	b.WriteString("## Bullets\n")
	for _, u := range bullets {
		// Carry the checkpoint id as a subtle provenance anchor; the LLM
		// is instructed to group but may cite these.
		fmt.Fprintf(&b, "- %s (source: %s)\n", u.Text, u.Source)
	}
	return b.String()
}

package dispatch

import (
	"context"
	"errors"
	"strings"
	"testing"
)

type stubTextGen struct {
	called    int
	prompt    string
	model     string
	returnMsg string
	returnErr error
}

func (s *stubTextGen) GenerateText(_ context.Context, prompt, model string) (string, error) {
	s.called++
	s.prompt = prompt
	s.model = model
	if s.returnErr != nil {
		return "", s.returnErr
	}
	return s.returnMsg, nil
}

func TestGenerateLocally_InvokesTextGeneratorWithVoiceAndBullets(t *testing.T) {
	t.Parallel()
	stub := &stubTextGen{returnMsg: "  Beep, boop.  \n"}
	bullets := []UsedBullet{
		{Text: "Fix CI flake", Source: "cloud_analysis"},
		{Text: "Reword messages", Source: "commit_message"},
	}
	voice := Voice{Name: "marvin", Text: "Marvin voice rules", IsPreset: true}

	got, err := GenerateLocally(context.Background(), bullets, voice, stub)
	if err != nil {
		t.Fatal(err)
	}
	if got != "Beep, boop." {
		t.Fatalf("expected trimmed output %q, got %q", "Beep, boop.", got)
	}
	if stub.called != 1 {
		t.Fatalf("expected 1 LLM call, got %d", stub.called)
	}
	for _, want := range []string{"Marvin voice rules", "Fix CI flake", "Reword messages"} {
		if !strings.Contains(stub.prompt, want) {
			t.Errorf("expected prompt to contain %q\nprompt:\n%s", want, stub.prompt)
		}
	}
}

func TestGenerateLocally_NoBullets(t *testing.T) {
