		flagWait        bool
	)

	cmd := &cobra.Command{
		Use:   "dispatch",
		Short: "Summarize recent agent work into a dispatch",
		Long: `Generate a dispatch summarizing recent agent work across repositories.

By default, the server synthesizes the dispatch using Entire's tokens.
Pass --local to run the synthesis on the user's own LLM (uses your
tokens).

Examples:
  entire dispatch
  entire dispatch --since "last monday"
  entire dispatch --branches main,release --since 14d
  entire dispatch --branches all --since 1w
  entire dispatch --org entireio --since 1w
  entire dispatch --generate --voice marvin
  entire dispatch --local --generate --voice ~/voice.md
  entire dispatch --format markdown > dispatch.md
  entire dispatch --format json > dispatch.json
  entire dispatch --dry-run --since 2w
`,
		RunE: func(cmd *cobra.Command, _ []string) error {
			ctx := cmd.Context()
			anyFlagSet := cmd.Flags().NFlag() > 0
			isTTY := term.IsTerminal(int(os.Stdin.Fd()))
			if !anyFlagSet && isTTY {
				return errors.New("wizard mode is not yet wired — pass at least one flag for now (wizard: see docs/superpowers/plans/2026-04-16-entire-dispatch-cli.md Task 12)")
			}

			opts, err := buildDispatchOptions(
				flagLocal, flagSince, flagUntil, flagBranches, flagRepos,
				flagOrg, flagGenerate, flagVoice, flagFormat, flagDryRun, flagWait,
				resolveCurrentBranch(ctx),
			)
			if err != nil {
				return err
			}
			return runAndRenderDispatch(cmd.OutOrStdout(), cmd.Context(), opts)
		},
	}

	cmd.Flags().BoolVar(&flagLocal, "local", false, "use local LLM tokens instead of server synthesis")
	cmd.Flags().StringVar(&flagSince, "since", "7d", "time window (Go duration, git-style, or ISO date)")
