	cmd.Flags().StringVar(&flagBranches, "branches", "", "comma-separated branches, or 'all'")
	cmd.Flags().StringSliceVar(&flagRepos, "repos", nil, "local repo paths (requires --local)")
	cmd.Flags().StringVar(&flagOrg, "org", "", "enumerate dispatches across an org")
	cmd.Flags().BoolVar(&flagGenerate, "generate", false, "synthesize LLM prose")
	cmd.Flags().StringVar(&flagVoice, "voice", "", "voice preset, file path, or literal description")
	cmd.Flags().StringVar(&flagFormat, "format", "text", "text | markdown | json")
	cmd.Flags().BoolVar(&flagDryRun, "dry-run", false, "preview without persisting")
	cmd.Flags().BoolVar(&flagWait, "wait", false, "block until pending analyses complete")

	return cmd
}

func buildDispatchOptions(
	flagLocal bool,
	flagSince, flagUntil, flagBranches string,
	flagRepos []string,
	flagOrg string,
	flagGenerate bool,
	flagVoice, flagFormat string,
	flagDryRun, flagWait bool,
	currentBranch string,
) (dispatch.Options, error) {
	opts := dispatch.Options{
		Mode:      dispatch.ModeServer,
		Since:     flagSince,
		Until:     flagUntil,
		RepoPaths: flagRepos,
		Org:       flagOrg,
		Generate:  flagGenerate,
		Voice:     flagVoice,
		Format:    flagFormat,
		DryRun:    flagDryRun,
		Wait:      flagWait,
	}
	if flagLocal {
		opts.Mode = dispatch.ModeLocal
	}

	branches, allBranches, err := dispatch.ParseBranches(flagBranches, currentBranch)
	if err != nil {
		return dispatch.Options{}, err
	}
	opts.Branches = branches
	opts.AllBranches = allBranches

	switch opts.Format {
	case "text", "markdown", "json":
	default:
		return dispatch.Options{}, fmt.Errorf("invalid --format %q (want text, markdown, or json)", opts.Format)
	}
	if opts.Voice != "" && !opts.Generate {
		return dispatch.Options{}, errors.New("--voice requires --generate")
	}
	return opts, nil
}

func runAndRenderDispatch(out io.Writer, ctx interface{ Done() <-chan struct{} }, opts dispatch.Options) error {
	d, err := dispatch.Run(ctxOrBackground(ctx), opts)
	if err != nil {
		return err
	}
	switch opts.Format {
	case "markdown":
		_, _ = fmt.Fprint(out, dispatch.RenderMarkdown(d))
	case "json":
		raw, err := dispatch.RenderJSON(d)
		if err != nil {
			return err
		}
		_, _ = out.Write(raw)
		_, _ = fmt.Fprintln(out)
	default:
		_, _ = fmt.Fprint(out, dispatch.RenderText(d))
	}
	return nil
}

// resolveCurrentBranch is a best-effort lookup; empty string if no repo.
// Implemented as a thin wrapper so we can make it pluggable in tests if we
// ever need to.
func resolveCurrentBranch(ctx interface{ Done() <-chan struct{} }) string {
	// TODO: wire real git HEAD resolution via go-git; for now rely on the
	// default coming from outside or accept empty (wizard / flags override).
	return ""
}

// ctxOrBackground avoids a direct context.Context import in this file's
// signatures; the caller already has a context and we just narrow it.
func ctxOrBackground(ctx interface{ Done() <-chan struct{} }) contextLike {
	return ctx.(contextLike)
}

// contextLike is the subset of context.Context that dispatch.Run needs. We
// keep this narrow so this file doesn't pretend to own context semantics.
type contextLike interface {
	Deadline() (deadline anyTime, ok bool)
	Done() <-chan struct{}
	Err() error
	Value(key any) any
}

type anyTime = interface{} //nolint:unused

