package cli

import (
	"context"
	"fmt"
	"io"

	"github.com/charmbracelet/huh"
	"github.com/entireio/cli/cmd/entire/cli/dispatch"
)

// runDispatchWizard drives the minimal huh-based interactive flow and runs the
// dispatch with the collected answers. Fires only on bare TTY invocation
// (no flags). Escape at any step cancels cleanly.
func runDispatchWizard(ctx context.Context, out io.Writer) error {
	var (
		mode     = "server"
		window   = "7d"
		customWindow string
		generate = "generate"
		voice    = "neutral"
		branchesChoice = "current"
		format   = "text"
	)

	form := NewAccessibleForm(
		huh.NewGroup(
			huh.NewSelect[string]().
				Title("Source mode").
				Description("Server uses Entire's tokens; local uses your own LLM.").
				Options(
					huh.NewOption("Server (free, uses Entire's tokens)", "server"),
					huh.NewOption("Local (uses your agent + tokens)", "local"),
				).
				Value(&mode),
		),
		huh.NewGroup(
			huh.NewSelect[string]().
				Title("Time window").
				Options(
					huh.NewOption("Last 24 hours", "1d"),
					huh.NewOption("Last 7 days", "7d"),
					huh.NewOption("Last 30 days", "30d"),
					huh.NewOption("Custom…", "custom"),
				).
				Value(&window),
			huh.NewInput().
				Title("Custom window (e.g. 2w, \"3 days ago\", 2026-04-09)").
				Value(&customWindow).
				WithHideFunc(func() bool { return window != "custom" }),
		),
		huh.NewGroup(
			huh.NewSelect[string]().
				Title("Branches").
				Options(
					huh.NewOption("Current branch only", "current"),
					huh.NewOption("All branches", "all"),
				).
				Value(&branchesChoice),
		),
		huh.NewGroup(
			huh.NewSelect[string]().
				Title("Generate LLM prose, or just bullets?").
				Options(
					huh.NewOption("Bullets only (fast, no tokens)", "bullets"),
					huh.NewOption("Generate full dispatch with voice", "generate"),
				).
				Value(&generate),
			huh.NewSelect[string]().
				Title("Voice").
				Options(
					huh.NewOption("Neutral product update (default)", "neutral"),
					huh.NewOption("Marvin — sardonic AI companion", "marvin"),
				).
				Value(&voice).
				WithHideFunc(func() bool { return generate != "generate" }),
		),
		huh.NewGroup(
			huh.NewSelect[string]().
				Title("Output format").
				Options(
					huh.NewOption("Text (for terminal)", "text"),
					huh.NewOption("Markdown (for docs)", "markdown"),
					huh.NewOption("JSON (for scripts)", "json"),
				).
				Value(&format),
		),
	)

	if err := form.Run(); err != nil {
		return handleFormCancellation(out, "dispatch", err)
	}

	effectiveWindow := window
	if window == "custom" {
		if customWindow == "" {
			return fmt.Errorf("custom window was empty")
		}
		effectiveWindow = customWindow
	}

	branches := ""
	if branchesChoice == "all" {
		branches = "all"
	}

	opts, err := buildDispatchOptions(
		mode == "local",
		effectiveWindow,
		"",
		branches,
		nil,
		"",
		generate == "generate",
		voice,
		format,
		false,
		false,
		"", // current branch unknown in wizard; passing empty means AllBranches or ParseBranches will complain
	)
	if err != nil {
		return err
	}
	if !opts.AllBranches && len(opts.Branches) == 0 {
		// Wizard can't resolve current branch without doing git work; if the user
		// picked "current" and we don't know it, fall back to all-branches.
		opts.AllBranches = true
	}

	// Print the equivalent CLI command so users learn the flag syntax.
	fmt.Fprintf(out, "\nEquivalent command:\n  %s\n\n", equivalentCommand(opts))

	return runAndRenderDispatch(ctx, out, opts)
}

func equivalentCommand(opts dispatch.Options) string {
	parts := []string{"entire dispatch"}
	if opts.Mode == dispatch.ModeLocal {
		parts = append(parts, "--local")
	}
	if opts.Since != "" && opts.Since != "7d" {
		parts = append(parts, fmt.Sprintf("--since %q", opts.Since))
	}
	if opts.AllBranches {
		parts = append(parts, "--branches all")
	}
	if opts.Generate {
		parts = append(parts, "--generate")
		if opts.Voice != "" && opts.Voice != "neutral" {
			parts = append(parts, fmt.Sprintf("--voice %s", opts.Voice))
		}
	}
	if opts.Format != "" && opts.Format != "text" {
		parts = append(parts, fmt.Sprintf("--format %s", opts.Format))
	}
	return joinWithSpace(parts)
}

func joinWithSpace(parts []string) string {
	out := ""
	for i, p := range parts {
		if i > 0 {
			out += " "
		}
		out += p
	}
	return out
}

