// ListCandidates returns all locally-indexed checkpoints as bullet candidates.
//
// Enrichment:
//   - Branch comes from CheckpointSummary.Branch (the branch recorded on the
//     condensed checkpoint metadata at creation time).
//   - CommitSubject comes from a single walk of reachable commits from HEAD
//     that looks for the Entire-Checkpoint trailer; the first commit referencing
//     a checkpoint wins (most recent in committer-time order).
//   - LocalSummaryTitle stays empty in v1 — reading per-session Intent strings
//     requires per-session metadata file traversal; not yet wired.
func (s strategyCandidateSource) ListCandidates(ctx context.Context) ([]Candidate, error) {
	infos, err := strategy.ListCheckpoints(ctx)
	if err != nil {
		return nil, fmt.Errorf("listing checkpoints: %w", err)
	}

	repo, err := strategy.OpenRepository(ctx)
	if err != nil {
		return nil, fmt.Errorf("opening repository: %w", err)
	}
	store := checkpoint.NewGitStore(repo)
	commitSubjectsByID := buildCheckpointCommitSubjects(ctx, repo)

	out := make([]Candidate, 0, len(infos))
	for _, info := range infos {
		c := Candidate{
			ID:           info.CheckpointID.String(),
			RepoFullName: s.repoFullName,
			CreatedAt:    info.CreatedAt,
			FilesTouched: info.FilesTouched,
		}
		if summary, err := store.ReadCommitted(ctx, info.CheckpointID); err == nil && summary != nil {
			c.Branch = summary.Branch
		}
		if subject, ok := commitSubjectsByID[info.CheckpointID.String()]; ok {
			c.CommitSubject = subject
		}
		out = append(out, c)
	}
	return out, nil
}

// buildCheckpointCommitSubjects walks commits reachable from HEAD looking for
// Entire-Checkpoint trailers. For each checkpoint ID found, it keeps the
// subject of the first (most recent) matching commit. Returns an empty map on
// any error — the enrichment is best-effort.
func buildCheckpointCommitSubjects(ctx context.Context, repo *git.Repository) map[string]string {
	out := make(map[string]string)
	head, err := repo.Head()
	if err != nil {
		return out
	}
	iter, err := repo.Log(&git.LogOptions{From: head.Hash(), Order: git.LogOrderCommitterTime})
	if err != nil {
		return out
	}
	defer iter.Close()

	_ = iter.ForEach(func(c *object.Commit) error {
		if err := ctx.Err(); err != nil {
			return err //nolint:wrapcheck // propagating context cancellation
		}
		cpID, found := trailers.ParseCheckpoint(c.Message)
		if !found {
			return nil
		}
		key := cpID.String()
		if _, exists := out[key]; exists {
			return nil
		}
		subject := c.Message
		if idx := strings.IndexByte(subject, '\n'); idx >= 0 {
			subject = subject[:idx]
		}
		out[key] = strings.TrimSpace(subject)
		return nil
	})
	return out
}

