package dispatch

import (
	"context"
	"path/filepath"
	"testing"

	"github.com/entireio/cli/cmd/entire/cli/testutil"
	"github.com/go-git/go-git/v6"
)

func TestBuildCheckpointCommitSubjects_FindsTrailerMatches(t *testing.T) {
	t.Parallel()
	dir := t.TempDir()
	testutil.InitRepo(t, dir)
	testutil.WriteFile(t, dir, "a.txt", "hello")
	testutil.GitAdd(t, dir, "a.txt")
	testutil.GitCommit(t, dir, "Fix CI flake\n\nEntire-Checkpoint: abcdef123456")
	testutil.WriteFile(t, dir, "b.txt", "world")
	testutil.GitAdd(t, dir, "b.txt")
	testutil.GitCommit(t, dir, "Update deps\n\nEntire-Checkpoint: 00112233aabb")
	testutil.WriteFile(t, dir, "c.txt", "no trailer")
	testutil.GitAdd(t, dir, "c.txt")
	testutil.GitCommit(t, dir, "Unrelated commit")

	repo, err := git.PlainOpen(dir)
	if err != nil {
		t.Fatal(err)
	}
	got := buildCheckpointCommitSubjects(context.Background(), repo)

	if got["abcdef123456"] != "Fix CI flake" {
		t.Fatalf("expected Fix CI flake for abcdef123456, got %q", got["abcdef123456"])
	}
	if got["00112233aabb"] != "Update deps" {
		t.Fatalf("expected Update deps for 00112233aabb, got %q", got["00112233aabb"])
	}
	if len(got) != 2 {
		t.Fatalf("expected exactly 2 matches, got %d: %+v", len(got), got)
	}
}

func TestBuildCheckpointCommitSubjects_MostRecentWins(t *testing.T) {
	t.Parallel()
	dir := t.TempDir()
	testutil.InitRepo(t, dir)
	testutil.WriteFile(t, dir, "a.txt", "a")
	testutil.GitAdd(t, dir, "a.txt")
	testutil.GitCommit(t, dir, "Initial attempt\n\nEntire-Checkpoint: abcdef123456")
	testutil.WriteFile(t, dir, "a.txt", "aa")
	testutil.GitAdd(t, dir, "a.txt")
	testutil.GitCommit(t, dir, "Refined attempt\n\nEntire-Checkpoint: abcdef123456")

	repo, err := git.PlainOpen(dir)
	if err != nil {
		t.Fatal(err)
	}
	got := buildCheckpointCommitSubjects(context.Background(), repo)

	if got["abcdef123456"] != "Refined attempt" {
		t.Fatalf("expected most-recent subject, got %q", got["abcdef123456"])
	}
}

func TestBuildCheckpointCommitSubjects_EmptyRepo(t *testing.T) {
	t.Parallel()
	dir := t.TempDir()
	testutil.InitRepo(t, dir)
	repo, err := git.PlainOpen(filepath.Clean(dir))
	if err != nil {
		t.Fatal(err)
	}
	got := buildCheckpointCommitSubjects(context.Background(), repo)
	if len(got) != 0 {
		t.Fatalf("expected empty map for empty repo, got %v", got)
	}
}

